"""nl — quran_b."""

T = {
"quran_081": ("Waarover ondervragen de mensen elkaar, aan het begin van soera An-Naba?", ["Over de grote tijding", "Over de regen", "Over de sterren", "Over de oogsten"], "«Waarover ondervragen zij elkaar? Over de grote tijding.»"),
"quran_082": ("Wat betekent «Al-Qari'ah», de titel van soera 101?", ["De Slaande Ramp", "De dageraad", "De karavaan", "De berg"], "«De Slaande Ramp! Wat is de Slaande Ramp? En wat doet jou weten wat zij is?» — het is een naam van de Laatste Dag."),
"quran_083": ("Wat wacht in soera Al-Qari'ah degene wiens weegschaal licht weegt?", ["Een afgrond (Hawiyah) als verblijf", "Een tuin", "Een bron", "Een huis"], "«Maar wat hem betreft wiens weegschaal licht weegt, zijn verblijf zal een afgrond zijn.»"),
"quran_084": ("Waartegen waarschuwt soera At-Takathur?", ["De wedijver in het vergaren, die afleidt", "Het reizen", "De honger", "Het zwijgen"], "«De wedijver in vermeerdering leidt jullie af, totdat jullie de graven bezoeken.»"),
"quran_085": ("Tegen wie opent soera Al-Humazah met «Wee…»?", ["Iedere lasteraar en kwaadspreker", "De reiziger", "De slaper", "De arme"], "«Wee iedere lasteraar en kwaadspreker, die rijkdom vergaart en telt.»"),
"quran_086": ("Wat vraagt soera Quraysh van Quraysh, in ruil voor de winter- en zomerreizen?", ["De Heer van dit Huis te aanbidden, die hen voedde en veilig stelde", "Muren te bouwen", "De handel te staken", "Naar Jemen te vertrekken"], "«Laat hen dan de Heer van dit Huis aanbidden, die hen tegen honger voedde en hen veilig stelde tegen vrees.»"),
"quran_087": ("Met welke vraag opent soera Ash-Sharh?", ["«Hebben Wij jouw borst niet verruimd?»", "«Heb je niet gezien?»", "«Wie heeft jou geschapen?»", "«Waar ga je heen?»"], "«Hebben Wij jouw borst niet voor jou verruimd?»"),
"quran_088": ("Waarbij zweert Allah aan het begin van soera At-Tin?", ["Bij de vijg, de olijf, de berg Sinai en deze veilige stad", "Bij de nacht en de dag", "Bij de sterren", "Bij de zee"], "«Bij de vijg en de olijf, bij de berg Sinai, en bij deze veilige stad.»"),
"quran_089": ("Hoe beschrijft soera At-Tin de schepping van de mens?", ["In de beste vorm", "Zwak en klein", "Uit vuur", "Uit licht"], "«Voorzeker, Wij hebben de mens in de beste gestalte geschapen.»"),
"quran_090": ("Bij welke stad zweert Allah aan het begin van soera Al-Balad?", ["Mekka, waar de Profeet ﷺ verbleef", "Medina", "Jeruzalem", "Ta'if"], "«Ik zweer bij deze stad, en jij bent een bewoner van deze stad.»"),
"quran_091": ("Wat is de «steile weg» die soera Al-Balad beschrijft?", ["Een slaaf bevrijden, een wees of een behoeftige voeden op een dag van honger", "De woestijn oversteken", "Een berg beklimmen", "De zee oversteken"], "«En wat doet jou weten wat de steile weg is? Het is het bevrijden van een slaaf, of het voeden op een dag van hevige honger van een verwante wees, of een behoeftige in ellende.»"),
"quran_092": ("Waarbij zweert Allah aan het begin van soera Al-Layl?", ["Bij de nacht wanneer die bedekt en de dag wanneer die verschijnt", "Bij de zee en de berg", "Bij de vijg en de olijf", "Bij de pen"], "«Bij de nacht wanneer die bedekt, en bij de dag wanneer die verschijnt… voorwaar, jullie streven is verschillend.»"),
"quran_093": ("Met welk gebod opent soera Al-A'la?", ["«Verheerlijk de naam van jouw Heer, de Allerhoogste»", "«Lees»", "«Sta op»", "«Luister»"], "«Verheerlijk de naam van jouw Heer, de Allerhoogste.»"),
"quran_094": ("Waarover spreekt het begin van soera Al-Ghashiyah?", ["De overweldigende gebeurtenis: de Laatste Dag", "Een reis", "Een markt", "Een veldslag"], "«Heeft het bericht van de Overweldigende jou bereikt?»"),
"quran_095": ("Over welk schepsel nodigt soera Al-Ghashiyah uit na te denken?", ["De kameel, en hoe hij geschapen is", "De leeuw", "De adelaar", "De vis"], "«Kijken zij dan niet naar de kamelen, hoe zij geschapen zijn?»"),
"quran_096": ("Waarbij zweert Allah aan het begin van soera Al-Buruj?", ["Bij de hemel met de sterrenbeelden", "Bij de aarde", "Bij de rivieren", "Bij de wolken"], "«Bij de hemel met de sterrenbeelden, en bij de beloofde Dag.»"),
"quran_097": ("Waarnaar verwijst «At-Tariq», de titel van soera 86?", ["De doordringende nachtster", "De deur", "De weg", "De donder"], "«Bij de hemel en de nachtelijke komer — en wat doet jou weten wat de nachtelijke komer is? Het is de doordringende ster.»"),
"quran_098": ("Welke gebeurtenis beschrijft het begin van soera Az-Zalzalah?", ["De aarde die door haar beving geschud wordt", "Een stortregen", "Een hevige wind", "Een verduistering"], "«Wanneer de aarde door haar laatste beving geschud wordt, en de aarde haar lasten uitwerpt.»"),
"quran_099": ("Welke maatstaf stelt het einde van soera Az-Zalzalah voor de daden?", ["Het gewicht van een stofdeeltje, zowel goed als kwaad", "Een schepel", "Een jaar", "Een hand"], "«Wie dan het gewicht van een stofdeeltje aan goeds doet, zal het zien; en wie het gewicht van een stofdeeltje aan kwaad doet, zal het zien.»"),
"quran_100": ("Waarnaar verwijst «Al-'Adiyat», de titel van soera 100?", ["De rennende paarden die hijgend galopperen", "De winden", "De golven", "De wolken"], "«Bij de rennenden, hijgend; en de vonkenslaanden bij het treffen; en de bestormers bij de dageraad.»"),
"quran_101": ("Hoe beschrijft soera Al-Baqarah het Boek in haar tweede vers?", ["Een boek waarover geen twijfel bestaat, een leiding voor de godvrezenden", "Een geschiedenisboek", "Een dichtbundel", "Een boek van louter wetten"], "«Dit is het Boek waarover geen twijfel bestaat, een leiding voor hen die Allah vrezen.»"),
"quran_102": ("Welk vers belooft de bewaring van de geopenbaarde Vermaning?", ["«Voorwaar, Wij hebben de Vermaning neergezonden, en voorwaar, Wij zijn haar bewaker»", "«Niemand zal haar lezen»", "«Zij zal vergeten worden»", "«Zij zal verborgen worden»"], "«Voorwaar, Wij zijn het die de Koran hebben neergezonden en voorwaar, Wij zijn er de bewaker van.»"),
"quran_103": ("Welk argument voert de Koran aan over zijn vrijheid van tegenspraak?", ["Was hij van een ander dan Allah gekomen, dan zouden zij er veel tegenspraak in vinden", "Dat hij kort is", "Dat hij in het Arabisch is", "Dat hij oud is"], "«Bedenken zij de Koran dan niet? Als hij van een ander dan Allah was geweest, dan zouden zij er veel tegenspraak in gevonden hebben.»"),
"quran_104": ("Wat zegt de Koran dat er met een berg zou zijn gebeurd, als hij daarop was neergezonden?", ["Hij zou zich vernederd hebben en uiteengespleten uit vrees voor Allah", "Hij zou geschitterd hebben", "Hij zou verplaatst zijn", "Hij zou groen geworden zijn"], "«Als Wij deze Koran op een berg hadden neergezonden, dan zou je die zich zien vernederen en uiteenspatten uit vrees voor Allah.»"),
"quran_105": ("Hoe gebiedt de Koran dat hij gereciteerd wordt, in soera Al-Muzzammil?", ["Afgemeten en duidelijk (tartil)", "Zo snel mogelijk", "In stilte", "Zingend"], "«En reciteer de Koran met afgemeten recitatie.»"),
"quran_106": ("Wat moet men doen wanneer de Koran gereciteerd wordt, volgens soera Al-A'raf?", ["Luisteren en zwijgen", "Hardop antwoorden", "Weggaan", "Schrijven"], "«En wanneer de Koran wordt gereciteerd, luister er dan naar en zwijg, opdat jullie barmhartigheid ontvangen.»"),
"quran_107": ("Wat gebiedt de Koran te zeggen voordat men begint te lezen?", ["Bij Allah toevlucht zoeken tegen de verworpen satan", "De verzen tellen", "De wassing hardop uitspreken", "Het laatste vers reciteren"], "«Wanneer jij de Koran leest, zoek dan bij Allah toevlucht tegen de verworpen satan.»"),
"quran_108": ("Waarom werd het Boek neergezonden, volgens soera Sad?", ["Opdat over zijn verzen nagedacht wordt en de bezitters van verstand vermaand worden", "Opdat het gekopieerd wordt", "Opdat het geteld wordt", "Opdat het verborgen wordt"], "«Dit is een gezegend Boek dat Wij aan jou hebben neergezonden, opdat zij over zijn verzen nadenken.»"),
"quran_109": ("Welke uitdaging richt soera Al-Isra tot mensen en djinn samen?", ["Iets voort te brengen als deze Koran, zelfs elkaar helpend", "De hemelen over te steken", "De sterren te tellen", "Een stad te bouwen"], "«Als de mensen en de djinn zich zouden verenigen om iets voort te brengen als deze Koran, dan zouden zij niet iets dergelijks kunnen voortbrengen, ook al zouden zij elkaar helpen.»"),
"quran_110": ("Welke smeekbede leert de Koran aangaande kennis?", ["«Mijn Heer, vermeerder mij in kennis»", "«Mijn Heer, geef mij rijkdom»", "«Mijn Heer, verleng mijn leven»", "«Mijn Heer, open de wegen voor mij»"], "«En zeg: mijn Heer, vermeerder mij in kennis.»"),
"quran_111": ("Hoe beschrijft soera Az-Zumar het beste van de neergezonden verhalen?", ["Een Boek van gelijkende, herhaalde delen, waarvan de huid huivert", "Een kort boek", "Een wetboek", "Een boek in dichtvorm"], "«Allah heeft het beste verhaal neergezonden: een consistent Boek waarin herhaling is. De huid van hen die hun Heer vrezen huivert ervan.»"),
"quran_112": ("Waarmee vergelijkt de Koran een goed woord, in soera Ibrahim?", ["Met een goede boom, met vaste wortel en takken in de hemel", "Met een rivier", "Met een berg", "Met een ster"], "«Een goed woord is als een goede boom, waarvan de wortel stevig staat en de takken in de hemel reiken; hij geeft zijn vruchten in elk seizoen.»"),
"quran_113": ("Waarmee vergelijkt soera Ar-Ra'd waarheid en valsheid?", ["Met het schuim dat de stroom meevoert, en wat de mensen baat en blijft", "Met twee bergen", "Met twee steden", "Met twee karavanen"], "«Wat het schuim betreft, dat verdwijnt als afval; maar wat de mensen baat blijft op de aarde.»"),
"quran_114": ("Waardoor komen de harten tot rust, volgens soera Ar-Ra'd?", ["Door het gedenken van Allah", "Door rijkdom", "Door reizen", "Door slaap"], "«Weet dat de harten tot rust komen door het gedenken van Allah.»"),
"quran_115": ("Wat zegt soera Al-Kahf over de inkt die nodig is om de woorden van Allah te schrijven?", ["De zee zou opdrogen voordat de woorden van zijn Heer uitgeput zijn", "Eén inktpot zou volstaan", "Eén nacht zou volstaan", "Zeven pennen zouden volstaan"], "«Als de zee inkt was voor de woorden van mijn Heer, dan zou de zee uitgeput raken voordat de woorden van mijn Heer uitgeput zijn.»"),
"quran_116": ("Hoeveel zeeën zouden volgens soera Luqman de woorden van Allah nog steeds niet uitputten?", ["Zeven zeeën erbij, en nog steeds niet genoeg", "Eén", "Drie", "Twaalf"], "«En als alle bomen op aarde pennen waren en de zee inkt, aangevuld met nog zeven zeeën, dan zouden de woorden van Allah niet uitgeput raken.»"),
"quran_117": ("Welk bezwaar zou volgens de Koran zijn geopperd, als hij in een vreemde taal aan een Arabische gezant was geopenbaard?", ["«Waarom zijn zijn verzen niet uitvoerig uitgelegd?»", "«Hij is te kort»", "«Hij is te lang»", "«Hij heeft geen titel»"], "«En als Wij er een Koran in een vreemde taal van hadden gemaakt, dan zouden zij zeggen: “Waarom zijn zijn verzen niet uitgelegd?”»"),
"quran_118": ("Waarheen leidt de Koran, volgens soera Al-Isra?", ["Naar wat het meest juist is", "Naar rijkdom", "Naar macht", "Naar rust"], "«Voorwaar, deze Koran leidt naar wat het meest juist is, en verkondigt de gelovigen die goede daden verrichten een grote beloning.»"),
"quran_119": ("Hoe beschrijft soera Yunus wat van de Heer is neergedaald?", ["Een vermaning, een genezing voor wat in de borsten is, leiding en barmhartigheid", "Een afrekening", "Een koninklijk decreet", "Een verdrag"], "«O mensen, er is een vermaning van jullie Heer tot jullie gekomen en een genezing voor wat in de borsten is, en een leiding en barmhartigheid voor de gelovigen.»"),
"quran_120": ("Hoe beschrijft soera Al-Baqarah de rol van de Koran als criterium?", ["Leiding voor de mensen, duidelijke bewijzen, en het onderscheid", "Een rekeningenboek", "Een verhalenbundel", "Een strafwetboek"], "«De maand Ramadan waarin de Koran werd neergezonden, als leiding voor de mensen en duidelijke bewijzen van de leiding en het onderscheid.»"),
"quran_121": ("Waarbij zweert Allah aan het begin van soera Qaf?", ["Bij de glorierijke Koran", "Bij de berg", "Bij de wind", "Bij de dageraad"], "«Qaf. Bij de eerbiedwaardige Koran.»"),
"quran_122": ("Waarnaar verwijst «Al-Mursalat», de titel van soera 77?", ["Zij die uitgezonden worden, de een na de ander", "De karavanen", "De sterren", "De rivieren"], "«Bij hen die uitgezonden worden in vlagen, de een na de ander.»"),
"quran_123": ("Welk register noemt soera Al-Mutaffifin voor de rechtschapenen?", ["'Illiyyun", "Sijjin", "Al-Lawh", "Az-Zabur"], "«Het register van de rechtschapenen is in 'Illiyyun… een beschreven boek, waarvan de nabije engelen getuigen.»"),
"quran_124": ("Met welke gebeurtenis opent soera Al-Inshiqaq?", ["De hemel die splijt", "De zee die overstroomt", "De aarde die groen wordt", "De zon die opkomt"], "«Wanneer de hemel splijt en naar haar Heer luistert, zoals het haar past.»"),
"quran_125": ("Met welk teken opent soera At-Takwir?", ["De zon die opgerold wordt", "De maan die splijt", "De wind die opsteekt", "De donder"], "«Wanneer de zon in duisternis wordt opgerold, en wanneer de sterren vallen en hun glans verliezen.»"),
"quran_126": ("Wat zegt het laatste vers van soera Al-Baqarah over de last die een ziel wordt opgelegd?", ["Allah belast een ziel niet boven haar vermogen", "Elke ziel draagt het dubbele", "Niemand wordt beproefd", "Alle lasten zijn gelijk"], "«Allah belast een ziel slechts naar haar vermogen.»"),
"quran_127": ("Waarmee vergelijkt de Koran het besteden op de weg van Allah?", ["Met een korrel die zeven aren voortbrengt, elk met honderd korrels", "Met een steen", "Met een put", "Met een lamp"], "«Het voorbeeld van hen die hun bezit besteden op de weg van Allah is als een korrel die zeven aren voortbrengt; in elke aar honderd korrels.»"),
"quran_128": ("Waarmee wordt de aalmoes vergeleken die door verwijt en krenking teniet wordt gedaan?", ["Met een rots bedekt met aarde, die door een stortbui kaal wordt gespoeld", "Met een vruchtboom", "Met een bron", "Met een huis"], "«Zijn voorbeeld is als dat van een gladde rots waarop aarde ligt en die door een stortbui wordt getroffen die haar kaal achterlaat.»"),
"quran_129": ("Waarmee vergelijkt de Koran de daden van de ongelovigen in soera An-Nur?", ["Met een luchtspiegeling op een vlakte, die de dorstige voor water houdt", "Met een berg", "Met regen", "Met een tuin"], "«En zij die ongelovig zijn — hun daden zijn als een luchtspiegeling in een vlakte, die de dorstige voor water houdt, totdat hij er komt en niets vindt.»"),
"quran_130": ("Welke vraag opent soera Al-'Ankabut, na de losse letters?", ["«Denken de mensen dat zij met rust gelaten worden om te zeggen “wij geloven” zonder beproefd te worden?»", "«Waar zijn de hemelen?»", "«Wie schiep de zee?»", "«Wat doen jullie morgen?»"], "«Denken de mensen dat zij met rust gelaten worden om te zeggen “wij geloven”, en dat zij niet beproefd worden?»"),
"quran_131": ("Hoe beschrijft soera Fatir de engelen in haar eerste vers?", ["Gezanten met vleugels, twee, drie of vier", "Geschapen uit klei", "Van onbekend aantal", "Op mensen gelijkend"], "«Lof zij Allah, Schepper van de hemelen en de aarde, die de engelen tot gezanten maakte met vleugels, twee, drie of vier.»"),
"quran_132": ("Welk teken noemt soera Ar-Rum aangaande echtgenoten?", ["Dat Hij tussen hen genegenheid en barmhartigheid heeft gelegd", "Dat zij apart leven", "Dat zij samenwerken", "Dat zij reizen"], "«En tot Zijn tekenen behoort dat Hij voor jullie uit jullie eigen midden echtgenoten schiep opdat jullie rust bij hen vinden, en Hij legde tussen jullie genegenheid en barmhartigheid.»"),
"quran_133": ("Welke twee tekenen noemt soera Ar-Rum vlak na de schepping van de hemelen en de aarde?", ["De verscheidenheid van talen en kleuren", "De dag en de nacht", "De wind en de regen", "De zee en de berg"], "«En tot Zijn tekenen behoort de schepping van de hemelen en de aarde en de verscheidenheid van jullie talen en jullie kleuren.»"),
"quran_134": ("Waaruit heeft Allah volgens soera Al-Anbiya alles wat leeft gemaakt?", ["Uit water", "Uit vuur", "Uit steen", "Uit lucht"], "«En Wij maakten uit water alles wat leeft. Zullen zij dan niet geloven?»"),
"quran_135": ("Welk argument geeft de Koran tegen een veelheid aan goden, in soera Al-Anbiya?", ["Waren er goden naast Allah geweest, dan zouden hemel en aarde te gronde zijn gegaan", "Zij zouden zich verbergen", "Zij zouden zwijgen", "Zij zouden verdwijnen"], "«Als er in de hemelen en op de aarde goden naast Allah waren geweest, dan zouden beide te gronde zijn gegaan.»"),
"quran_136": ("Welke drie zaken gebiedt Allah volgens vers 16:90?", ["Rechtvaardigheid, voortreffelijkheid, en het geven aan verwanten", "Vasten, gebed en bedevaart", "Handel, reizen en schrijven", "Zwijgen, geduld en afzondering"], "«Voorwaar, Allah gebiedt rechtvaardigheid, goed gedrag en het geven aan verwanten.»"),
"quran_137": ("Waaruit komt volgens soera An-Nahl een drank van verschillende kleuren waarin genezing is voor de mensen?", ["Uit de buiken van de bijen", "Uit de zee", "Uit de palmbomen", "Uit bergbronnen"], "«Uit hun buiken komt een drank van verschillende kleuren waarin genezing is voor de mensen.»"),
"quran_138": ("Hoe opent soera Ar-Rahman?", ["«De Erbarmer heeft de Koran onderwezen»", "«Bij de nacht»", "«Lof zij Allah»", "«Lees»"], "«De Erbarmer heeft de Koran onderwezen, de mens geschapen, en hem de duidelijke uitdrukking geleerd.»"),
"quran_139": ("In hoeveel groepen verdeelt soera Al-Waqi'ah de mensen op de Laatste Dag?", ["Drie", "Twee", "Vier", "Zeven"], "«En jullie worden in drie soorten verdeeld: de mensen van de rechterzijde, de mensen van de linkerzijde, en de voorgangers.»"),
"quran_140": ("Waarmee vergelijkt de Koran hen die de Thora dragen zonder ernaar te handelen?", ["Met een ezel die boeken draagt", "Met een vogel", "Met een berg", "Met een schip"], "«Het voorbeeld van hen aan wie de Thora werd toevertrouwd en die haar vervolgens niet op zich namen, is als dat van een ezel die boekdelen draagt.»"),
"quran_141": ("Welke vrouw houdt de Koran de gelovigen als voorbeeld voor, met haar verzoek om een huis bij Allah?", ["De vrouw van Farao", "De koningin van Saba", "De vrouw van Nuh", "De vrouw van Lut"], "«En Allah geeft een voorbeeld voor hen die geloven: de vrouw van Farao, toen zij zei: “Mijn Heer, bouw voor mij bij U een huis in het Paradijs.”»"),
"quran_142": ("Onder welke andere naam is soera Al-Ikhlas vaak bekend, naar haar onderwerp?", ["De soera van de eenheid (at-tawhid)", "De soera van de reis", "De soera van het licht", "De soera van de buit"], "Al-Ikhlas, «zuivere toewijding», wordt ook de soera van tawhid genoemd, want zij beschrijft Allah als de Ene."),
"quran_143": ("Wat ontkent het derde vers van soera Al-Ikhlas?", ["Dat Hij verwekte of verwekt werd", "Dat Hij machtig is", "Dat Hij hoort", "Dat Hij schept"], "«Hij verwekt niet en Hij is niet verwekt.»"),
"quran_144": ("Waartegen zoekt soera An-Nas toevlucht?", ["De terugtrekkende influisteraar, van de djinn en de mensen", "De storm", "De ziekte", "De armoede"], "«…tegen het kwaad van de terugtrekkende influisteraar, die in de borsten van de mensen influistert, van de djinn en de mensen.»"),
"quran_145": ("Hoeveel afzonderlijke kwaden noemt soera Al-Falaq na «het kwaad van wat Hij geschapen heeft»?", ["Drie: de invallende nacht, zij die op knopen blazen, en de benijder", "Eén", "Vijf", "Zeven"], "«…tegen het kwaad van de duisternis wanneer die invalt, tegen het kwaad van hen die op knopen blazen, en tegen het kwaad van een benijder wanneer hij benijdt.»"),
"quran_146": ("Welk vers van Al-Fatihah verwoordt de kern van de aanbidding en van het vragen om hulp?", ["«U alleen aanbidden wij en U alleen vragen wij om hulp»", "«Lof zij Allah»", "«Leid ons»", "«Heerser van de Dag des Oordeels»"], "«U alleen aanbidden wij en U alleen vragen wij om hulp.»"),
"quran_147": ("Welk verzoek sluit soera Al-Fatihah af?", ["Geleid te worden op het rechte pad, het pad van hen die begunstigd zijn", "Rijkdom", "Overwinning", "Een lang leven"], "«Leid ons op het rechte pad, het pad van hen aan wie U gunst hebt geschonken.»"),
"quran_148": ("Welke twee soorten verzen onderscheidt soera Al-'Imran?", ["Duidelijke verzen (muhkamat) en meerduidige verzen (mutashabihat)", "De lange en de korte", "De Mekkaanse en de Medinensische", "De gereciteerde en de geschreven"], "«Hij is het die het Boek aan jou heeft neergezonden: daarin zijn eenduidige verzen — zij zijn de grondslag van het Boek — en andere die meerduidig zijn.»"),
"quran_149": ("Welk beginsel stelt vers 2:106 over vervangen verzen?", ["Allah brengt een beter of gelijkwaardig vers", "Zij worden zonder vervanging gewist", "Zij worden vergeten", "Zij worden door mensen herschreven"], "«Wij schaffen geen vers af of doen het vergeten of Wij brengen een beter of daaraan gelijk vers.»"),
"quran_150": ("Waarover zal de Gezant ﷺ bij zijn Heer klagen, volgens soera Al-Furqan?", ["Dat zijn volk deze Koran in de steek heeft gelaten", "Dat hij vermoeid is", "Dat hij alleen is", "Dat hij arm is"], "«En de Gezant zal zeggen: “Mijn Heer, voorwaar, mijn volk heeft deze Koran als iets verlatens beschouwd.”»"),
}
